import random
import sys
sys.path.insert(0, r"C:\Users\刘康鑫\AppData\Local\Temp\sigma-eval-tyy9_0ks\workspace")
from roman import from_roman, to_roman

def test_fourteen() -> None:
    assert to_roman(14) == 'XIV'

def test_mcmxciv() -> None:
    assert from_roman('MCMXCIV') == 1994

# 额外的一致性校验:所有 1..3999 往返一致
def test_roundtrip_all() -> None:
    for n in range(1, 4000):
        s = to_roman(n)
        assert from_roman(s) == n, (n, s, from_roman(s))

def test_invalid_inputs() -> None:
    bad_to = [0, -1, 4000, -100, 1.5, "10", None, True]
    for v in bad_to:
        try:
            to_roman(v)
        except ValueError:
            pass
        else:
            raise AssertionError(f"to_roman 未拒绝: {v!r}")
    bad_from = ["", "IIII", "VV", "IL", "IC", "DM", "MMMM", "xiv", "V ", "IIIV", "ABC", None, 42]
    for v in bad_from:
        try:
            from_roman(v)
        except ValueError:
            pass
        else:
            raise AssertionError(f"from_roman 未拒绝: {v!r}")

if __name__ == "__main__":
    test_fourteen(); test_mcmxciv(); test_roundtrip_all(); test_invalid_inputs()
    print("ALL CHECKS PASSED")
EOF
